def earliest_arrival(n: int, connections: list[tuple[int, int, int, int]], source: int, target: int, start: int, change: int, max_transfers: int) -> int:
    if source == target:
        return start

    INF = 10**30

    if max_transfers < 0:
        return -1

    first = [INF] * n
    for u, v, depart, arrive in connections:
        if u == source and start <= depart:
            if arrive < first[v]:
                first[v] = arrive

    answer = first[target]

    if max_transfers == 0:
        return -1 if answer >= INF else answer

    prev = first
    for _ in range(max_transfers):
        current = [INF] * n
        any_update = False

        for u, v, depart, arrive in connections:
            prev_time = prev[u]
            if prev_time != INF and prev_time + change <= depart:
                if arrive < current[v]:
                    current[v] = arrive
                    any_update = True

        if current[target] < answer:
            answer = current[target]

        if not any_update:
            return -1 if answer >= INF else answer

        prev = current

    return -1 if answer >= INF else answer
